      "rank": 1,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Alan H. Guth",
        "Alexei A. Starobinsky",
        "Viatcheslav F. Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and quantum-seeded structure supply a remarkably powerful physical account of the observed large-scale universe.",
        "attribution": "Guth initiated inflation, while Starobinsky and Mukhanov made central theoretical contributions to its realizations and perturbation predictions.",
        "maturity": "Its principal predictions have been tested extensively through cosmological observations over decades.",
        "uncertainties": [
          "The direct primordial gravitational-wave signature remains unobserved.",
          "Several inflationary mechanisms and contributors complicate a uniquely bounded attribution."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Imaging the immediate environment of a black hole is an exceptional observational advance in gravitation and astronomy.",
        "attribution": "Falcke provided decisive early scientific vision for black-hole imaging and Doeleman led the VLBI effort that made it practical.",
        "maturity": "The result has been independently strengthened by images of two very different black-hole systems.",
        "uncertainties": [
          "The accomplishment rests on a vast collaboration, making individual credit intrinsically difficult."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Matthew Colless",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "BAO transformed a fossil feature of the early universe into a precise geometrical probe of cosmic expansion.",
        "attribution": "Eisenstein, Colless, and Cole were central to establishing and measuring the standard-ruler method in galaxy surveys.",
        "maturity": "The technique is mature, repeatedly confirmed, and now central to precision cosmology.",
        "uncertainties": [
          "The theoretical origin and observational development involved a broad community."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP made the cosmic microwave background a precision testbed for the physical parameters and history of the universe.",
        "attribution": "Bennett and Page led the experimental enterprise, while Spergel was central to extracting its cosmological implications.",
        "maturity": "Its measurements have endured comparison with later experiments and remain foundational.",
        "uncertainties": [
          "The appropriate division of credit between WMAP and later CMB missions requires care."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Marta Burgay",
        "Michael Kramer"
      ],
      "assessment": {
        "nobel_worthiness": "The double pulsar furnished uniquely clean strong-field tests of general relativity in a natural laboratory.",
        "attribution": "Burgay's discovery and Kramer's leading timing and interpretation work form a coherent core of credit.",
        "maturity": "Long-baseline timing has produced increasingly stringent and durable tests.",
        "uncertainties": [
          "Credit for the discovery and observational program extends beyond two individuals."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "The neutron-star-merger kilonova connected gravitational-wave astronomy to the cosmic origin of heavy elements.",
        "attribution": "Metzger and Kasen supplied key predictive interpretation, and Tanvir was central to the observational identification.",
        "maturity": "The multimessenger event gave compelling evidence for the mechanism and initiated a vigorous observational field.",
        "uncertainties": [
          "The relative contribution of mergers to the full r-process inventory remains under active study."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Francis Halzen",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "High-energy neutrino astronomy opened a genuinely new observational channel onto violent cosmic accelerators.",
        "attribution": "Halzen and Spiering were long-standing scientific leaders in conceiving and realizing IceCube.",
        "maturity": "The diffuse flux and astrophysical associations have moved the field beyond a single anomalous observation.",
        "uncertainties": [
          "The discovery and detector construction were deeply collective efforts."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Frans Pretorius",
        "Manuela Campanelli",
        "John G. Baker"
      ],
      "assessment": {
        "nobel_worthiness": "Stable numerical-relativity simulations made quantitative binary-black-hole gravitational-wave astronomy possible.",
        "attribution": "Pretorius, Campanelli, and Baker were pivotal in resolving the longstanding merger-simulation problem.",
        "maturity": "The methods have been repeatedly validated against gravitational-wave observations and are indispensable to their interpretation.",
        "uncertainties": [
          "Several near-simultaneous breakthroughs and earlier foundational developments complicate priority."
        ]
      }
    }
  ]
}
